"""Maybe deciders follow the normal declaration evaluation lifecycle."""

import pytest

import factory


@pytest.mark.parametrize('probability, expected', [(0, 'no'), (100, 'yes')])
def test_faker_decider_defaults(probability, expected):
    class SampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker('pybool', locale='en_US', truth_probability=probability),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert SampleFactory()['result'] == expected


def test_decider_context_is_unrolled():
    class SampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker(
                'pybool',
                truth_probability=factory.LazyFunction(lambda: 100),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert SampleFactory()['result'] == 'yes'


def test_wrapped_decider_and_branch_overrides():
    class SampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration=factory.Faker('pyint', min_value=1, max_value=1),
            no_declaration=0,
        )

    assert SampleFactory(result__min_value=7, result__max_value=7)['result'] == 7
